using System.Text.Json;
internal static class LibraryRowAcceptanceTests{
 internal static async Task Run(){
  var temp=Path.Combine(Path.GetTempPath(),"LibraryRowAccept-"+Guid.NewGuid().ToString("N"));var h=new SimAssemblyHeader("01PART                ","fixture","V1.2","PART                ","PART","A","202020","A",false);var store=new SimLibraryBomStore(temp,()=>[h]);var key=h.SourceKeyRaw;
  SimPersona P(params string[] rights)=>new("tester","tester","Fixture","ACTIVE",[],rights,false,"fixture");SimPersona author=P("assembly_library.view","assembly_library.edit"),viewer=P("assembly_library.view"),both=P("assembly_library.view","assembly_library.edit","technical_review.disposition");
  void Check(bool b,string name){if(!b)throw new Exception(name);}async Task Reject(Func<Task> f,string name){try{await f();}catch(Exception e)when(e is SimRfqIntakeProblem or LibraryBomPermissionException){return;}throw new Exception("Expected rejection: "+name);}
  LibraryRowEdit Row(string find,string qty)=>new(Guid.NewGuid().ToString(),find,"CPN-"+find,"Resistor",qty,"EA","R"+find,"CUSTOMER","","",true,false,"",false);
  var a=Row("1","1");var b=Row("2","");var v=await store.Get(key,author);v=await store.Change(new(key,v.Token,"START"),author);
  LibraryBomCommand Action(string action,LibraryRowEdit[] rows,string rowId)=>new(key,v.Token,action,DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",PreparationAssessed:true,Rows:rows,RowId:rowId);
  await Reject(async()=>await store.Change(Action("ACCEPT_ROW",[a with{Quantity=""},b],a.Id),author),"invalid quantity");Check((await store.Get(key,author)).Token==v.Token,"invalid accept saves nothing");await Reject(async()=>await store.Change(Action("ACCEPT_ROW",[a,b],a.Id),viewer),"viewer cannot accept");
  var stale=v.Token;v=await store.Change(Action("ACCEPT_ROW",[a,b with{Notes="pending neighbor preserved"}],a.Id),author);Check(v.Record.Draft!.Rows[0].Acceptance!.Actor.Id==author.Id,"persisted actor");Check(v.Record.Draft.Rows[1].Quantity==""&&v.Record.Draft.Rows[1].Notes=="pending neighbor preserved","save incomplete neighboring edits");Check(SimLibraryBomStore.RowAccepted(v.Record.Draft,v.Record.Draft.Rows[0]),"fingerprint valid");Check((await new SimLibraryBomStore(temp,()=>[h]).Get(key,author)).Record.Draft!.Rows[0].Acceptance is not null,"reopen accepted");await Reject(async()=>await store.Change(Action("EDIT_ROW",[a,b],a.Id) with{ExpectedToken=stale},author),"stale edit");await Reject(async()=>await store.Change(new(key,v.Token,"SUBMIT"),author),"remaining unaccepted row blocks submission");
  v=await store.Change(Action("EDIT_ROW",[a,b],a.Id),author);Check(v.Record.Draft!.Rows[0].Acceptance is null,"edit clears accepted state");v=await store.Change(Action("ACCEPT_ROW",[a,b],a.Id),author);v=await store.Change(Action("SAVE",[a with{Quantity="2"},b],a.Id),author);Check(v.Record.Draft!.Rows[0].Acceptance is null,"quantity edit invalidates");a=a with{Quantity="2"};v=await store.Change(Action("ACCEPT_ROW",[a,b],a.Id),author);
  v=await store.Change(Action("SAVE",[a,b],a.Id) with{DrawingRevision="B"},author);Check(v.Record.Draft!.Rows[0].Acceptance is null,"revision context invalidates");v=await store.Change(Action("ACCEPT_ROW",[a,b],a.Id),author);v=await store.Change(Action("SAVE",[a with{SourcePartNumber="CHANGED"},b],a.Id),author);Check(v.Record.Draft!.Rows[0].Acceptance is null,"PN change invalidates");a=a with{SourcePartNumber="CHANGED"};
  await Reject(async()=>await store.Change(Action("ACCEPT_ROW",[a with{PreparationRequired=true},b],a.Id),author),"unfinished preparation blocks row");await Reject(async()=>await store.Change(Action("ACCEPT_ROW",[a,b with{Find="1"}],a.Id),author),"duplicate Find");v=await store.Change(Action("ACCEPT_ROW",[a,b],a.Id),author);b=b with{Quantity="1"};v=await store.Change(Action("ACCEPT_ROW",[a,b],b.Id),author);Check(v.Record.Draft!.Rows.All(r=>SimLibraryBomStore.RowAccepted(v.Record.Draft,r)),"both accepted");
  v=await store.Change(new(key,v.Token,"SUBMIT"),author);await Reject(async()=>await store.Change(Action("EDIT_ROW",[a,b],a.Id),author),"submitted immutable");v=await store.Change(new(key,v.Token,"APPROVE",ReviewId:v.Record.Reviews.Last().Id,Comments:"Fixture final review"),both,true);await Reject(async()=>await store.Change(Action("ACCEPT_ROW",[a,b],a.Id),author),"approved immutable");Check(v.Record.History.Any(e=>e.Action=="EDIT_ROW")&&v.Record.History.Any(e=>e.Action=="ACCEPT_ROW"),"audit history");
  var sourceRoot=Path.Combine(temp,"source-case");var sourceStore=new SimLibraryBomStore(sourceRoot,()=>[h]);var sv=await sourceStore.Get(key,author);sv=await sourceStore.Change(new(key,sv.Token,"START"),author);
  var txt=string.Join('\t',SimVproParser.Headers)+"\tDRAW#=PART REV A\n"+string.Join('\t',new[]{"001","CPN","Resistor","","1","1","EA","1","0","0","0","P",""})+"\n"+string.Join('\t',new[]{"002","","(1) R1","","0","0","","0","0","0","0","",""})+"\n";var bytes=System.Text.Encoding.ASCII.GetBytes(txt);sv=await sourceStore.Change(new(key,sv.Token,"IMPORT",TextBase64:Convert.ToBase64String(bytes),FileName:"fixture.txt"),author);var sr=sv.Record.Draft!.Rows[0];var edit=new LibraryRowEdit(sr.Id,sr.Find,sr.SourcePartNumber,sr.Description,sr.Quantity,sr.Unit,sr.ReferenceDesignators,"CUSTOMER","","",true,false,"",false);var accept=new LibraryBomCommand(key,sv.Token,"ACCEPT_ROW",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",PreparationAssessed:true,Rows:[edit],RowId:sr.Id);
  var evidencePath=Path.Combine(sourceRoot,"assembly-library-v1","evidence",sv.Record.Draft.EvidenceHash+".txt");await File.WriteAllTextAsync(evidencePath,"changed source");await Reject(async()=>await sourceStore.Change(accept,author),"changed source bytes");Check((await sourceStore.Get(key,author)).Token==sv.Token,"source failure unchanged");await File.WriteAllBytesAsync(evidencePath,bytes);await Reject(async()=>await sourceStore.Change(accept with{BomRevision="B"},author),"source revision mismatch");sv=await sourceStore.Change(accept,author);Check(sv.Record.Draft!.Rows[0].Acceptance is not null,"verified source row accepted");
  sv=await sourceStore.Change(new(key,sv.Token,"ALTERNATE",RowId:sr.Id,AlternateDecision:"ADD",PartNumber:"ALT-1"),author);Check(sv.Record.Draft!.Rows[0].Acceptance is null,"alternate change invalidates accepted row");await Reject(async()=>await sourceStore.Change(accept with{ExpectedToken=sv.Token},author),"proposed alternate blocks row even with primary identity");var aid=sv.Record.Draft.Rows[0].Alternates[0].Id;sv=await sourceStore.Change(new(key,sv.Token,"ALTERNATE",RowId:sr.Id,AlternateId:aid,AlternateDecision:"APPROVED",Comments:"Fixture evidence"),both);sv=await sourceStore.Change(accept with{ExpectedToken=sv.Token,Rows=[edit with{SelectedAlternateId=aid}]},author);Check(sv.Record.Draft!.Rows[0].SelectedAlternateId==aid&&sv.Record.Draft.Rows[0].Acceptance is not null,"selected eligible PN then row acceptance");sv=await sourceStore.Change(new(key,sv.Token,"ALTERNATE",RowId:sr.Id,AlternateId:aid,AlternateDecision:"REJECTED",Comments:"Fixture revoked"),both);Check(sv.Record.Draft!.Rows[0].Acceptance is null&&sv.Record.Draft.Rows[0].SelectedAlternateId is null,"revoked selected alternate invalidates row");
  sv=await sourceStore.Change(accept with{ExpectedToken=sv.Token},author);Check(sv.Record.Draft!.Rows[0].Acceptance is not null,"rejected alternate counts as reviewed without selection");
  sv=await sourceStore.Change(new(key,sv.Token,"ALTERNATE",RowId:sr.Id,AlternateDecision:"ADD",PartNumber:"ALT-2"),author);await Reject(async()=>await sourceStore.Change(accept with{ExpectedToken=sv.Token},author),"second proposed alternate still blocks");var pendingRow=sv.Record.Draft!.Rows[0];Check(SimLibraryBomStore.Blockers(sv.Record.Draft with{Rows=[pendingRow with{Alternates=[pendingRow.Alternates[0] with{Status="STALE"}]}]}).Any(e=>e.Contains("need review")),"stale decision blocked");
  Console.WriteLine("PASS persisted Accept/Edit/reaccept, row fingerprint invalidation, neighboring incomplete edits preserved, no partial invalid save, preparation/duplicate/identity/quantity validation, stale token, permissions, submission gate and immutable approved version.");
 }
}
